for (size_t i = start; i < end; i++) {
    Particle* particle = &particles[i];
    particle->acceleration = glm::vec3(0.0f);

    glm::ivec3 cell = getCell(particle, h);
    glm::ivec3 nearCells[27];
    size_t nearCellCount = 0;

    for (int x = -1; x <= 1; x++) {
        for (int y = -1; y <= 1; y++) {
            for (int z = -1; z <= 1; z++) {
                nearCells[nearCellCount++] = cell + glm::ivec3(x, y, z);
            }
        }
    }

    for (size_t c = 0; c < nearCellCount; c++) {
        uint32_t hash = getHash(nearCells[c]);
        if (hash >= TABLE_SIZE) continue;

        uint32_t index = particleTable[hash];
        if (index == NO_PARTICLE) continue;

        while (index < particleCount && getHash(getCell(&particles[index], h)) == hash) {
            Particle* neighbor = &particles[index];
            glm::vec3 dist = particle->position - neighbor->position;
            float distNorm = glm::length(dist);

            if (distNorm < h && distNorm > 0) {
                glm::vec3 dir = dist / distNorm;
                float V = particle->mass / particle->density;
                float VN = neighbor->mass / neighbor->density;
                float Vavg = (V + VN) * 0.5f;

                // Pressure force
                float pressureForce = spikyGrad * (particle->pressure + neighbor->pressure) * Vavg;
                particle->acceleration -= pressureForce * dir;

                // Viscosity force
                float viscosityForce = viscosity * spikyLap * Vavg;
                particle->acceleration += viscosityForce * (neighbor->velocity - particle->velocity);
            }
            index++;
        }
    }

    particle->acceleration /= particle->mass;
}

